describe('Color Contrast Accessibility Tests', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
    });

    it('should have sufficient color contrast for text elements', () => {
        cy.get('body').find('*').each(($el) => {
            const color = $el.css('color');
            const backgroundColor = $el.css('background-color');
            if (color && backgroundColor) {
                cy.task('checkContrast', { color, backgroundColor }).then((result) => {
                    expect(result).to.be.greaterThan(4.5); // AA standard for normal text
                });
            }
        });
    });

    it('should fail if any text element does not meet the color contrast standards', () => {
        cy.get('body').find('*').each(($el) => {
            const color = $el.css('color');
            const backgroundColor = $el.css('background-color');
            if (color && backgroundColor) {
                cy.task('checkContrast', { color, backgroundColor }).then((result) => {
                    if (result < 4.5) {
                        cy.log(`Element ${$el.prop('tagName')} does not meet contrast standards`);
                        expect(result).to.be.greaterThan(4.5); // This will fail the test
                    }
                });
            }
        });
    });
});
